class CatalogueLabels {
 final Map<String,String> labels,ids,codes;
 CatalogueLabels._(this.labels,this.ids,this.codes);
 factory CatalogueLabels.fromMetadata(Object? raw,String locale){if(raw is! Map||raw['kind']!='verified_metadata_export'||!['en','fr','es'].contains(locale)||raw['controls'] is! List||raw['locales'] is! Map)throw const FormatException('Unverified component metadata');final words=Map<String,String>.from((raw['locales'] as Map)[locale] as Map),ids=<String,String>{},codes=<String,String>{};for(final r in raw['controls'] as List){if(r is! Map||r['key'] is! String||r['testId'] is! String||r['componentCode'] is! String||r['controlId'] is! int||(r['controlId'] as int)<=0||!RegExp(r'^[a-z][a-z0-9-]{0,127}$').hasMatch(r['testId'] as String)||ids.containsKey(r['key'])||!words.containsKey(r['key']))throw const FormatException('Invalid component binding');ids[r['key'] as String]=r['testId'] as String;codes[r['key'] as String]=r['componentCode'] as String;}return CatalogueLabels._(Map.unmodifiable(words),Map.unmodifiable(ids),Map.unmodifiable(codes));}
 String text(String key){final value=labels[key];if(value==null||value.trim().isEmpty)throw ArgumentError('Registered label required');return value;}
 String id(String key,String component,{String suffix=''}){if(codes[key]!=component||!ids.containsKey(key)||suffix.isNotEmpty&&!RegExp(r'^-[a-z0-9_-]{1,100}$').hasMatch(suffix))throw ArgumentError('Registered component kind required');return ids[key]!+suffix;}
 Widget identify(String key,String component,Widget child,{String suffix=''})=>Semantics(identifier:id(key,component,suffix:suffix),child:child);
}
class PrimeCatalogueAction extends StatefulWidget {
 final CatalogueLabels labels;final String scope,control,suffix;final Future<void> Function()? action;final bool disabled,busy;final bool? pressed;final Object? operationKey;final String successKey,errorKey;
 const PrimeCatalogueAction({super.key,required this.labels,required this.scope,required this.control,this.action,this.suffix='',this.disabled=false,this.busy=false,this.pressed,this.operationKey,this.successKey='success',this.errorKey='actionError'});
 @override State<PrimeCatalogueAction> createState()=>_PrimeCatalogueActionState();
}
class _PrimeCatalogueActionState extends State<PrimeCatalogueAction>{bool _busy=false;String? _status;int _epoch=0;@override void didUpdateWidget(covariant PrimeCatalogueAction old){super.didUpdateWidget(old);if(old.scope!=widget.scope||old.control!=widget.control||old.operationKey!=widget.operationKey){_epoch++;_busy=false;_status=null;}}Future<void> _run()async{if(_busy||widget.disabled||widget.busy||widget.action==null)return;final epoch=_epoch,action=widget.action!;setState((){_busy=true;_status='loading';});try{await action();if(mounted&&epoch==_epoch)setState(()=>_status=widget.successKey);}catch(_){if(mounted&&epoch==_epoch)setState(()=>_status=widget.errorKey);}finally{if(mounted&&epoch==_epoch)setState(()=>_busy=false);}}@override void dispose(){_epoch++;super.dispose();}@override Widget build(BuildContext context){final busy=_busy||widget.busy,l=widget.labels;return Column(mainAxisSize:MainAxisSize.min,children:[l.identify(widget.control,'prime_button',Semantics(button:true,enabled:!busy&&!widget.disabled&&widget.action!=null,toggled:widget.pressed,value:busy?l.text('loading'):null,child:TextButton(style:widget.pressed==true?TextButton.styleFrom(backgroundColor:Theme.of(context).colorScheme.primary,foregroundColor:Theme.of(context).colorScheme.onPrimary):null,onPressed:busy||widget.disabled||widget.action==null?null:_run,child:Text(l.text(widget.control)))),suffix:widget.suffix),if(_status!=null)Semantics(liveRegion:true,child:Text(l.text(_status!)))]);}}
class PrimeComponentKit {
 final CatalogueLabels labels;final String scope;
 PrimeComponentKit(this.labels,this.scope){if(scope.trim().isEmpty||scope.length>1024)throw ArgumentError('Component scope required');}
 Widget button(String key,Future<void> Function()? action,{bool disabled=false,bool busy=false,bool? pressed,String suffix=''})=>PrimeCatalogueAction(labels:labels,scope:scope,control:key,action:action,disabled:disabled,busy:busy,pressed:pressed,suffix:suffix);
 Widget field(String key,TextEditingController controller,{bool enabled=true,bool required=false})=>labels.identify(key,key=='multiline'?'prime_textarea_web':'prime_text_field',TextFormField(controller:controller,enabled:enabled,maxLines:key=='multiline'?null:1,decoration:InputDecoration(labelText:labels.text(key)),validator:(value)=>required&&(value?.trim().isEmpty??true)?labels.text('required'):null));
 Widget select(Map<String,String> options,String? value,ValueChanged<String?>? changed){if(options.length>100)throw ArgumentError('Bounded options required');return labels.identify('select','prime_dropdown_web',DropdownButtonFormField<String>(initialValue:value,decoration:InputDecoration(labelText:labels.text('select')),onChanged:changed,items:[for(final e in options.entries)DropdownMenuItem(value:e.key,child:Text(e.value))]));}
 Widget boolean(String key,bool value,ValueChanged<bool>? changed)=>key=='switch'?PrimeCatalogueSwitch(labels:labels,value:value,changed:changed):labels.identify(key,'prime_checkbox_web',CheckboxListTile(title:Text(labels.text(key)),value:value,onChanged:changed==null?null:(v)=>changed(v??false)));
 Widget radio(Map<String,String> options,String? value,ValueChanged<String?> changed,{bool enabled=true})=>PrimeCatalogueRadio(labels:labels,options:options,value:value,changed:changed,enabled:enabled);
 Widget card(String key,Widget child)=>labels.identify(key,'prime_card',Card(child:child));
 Widget badge(String value)=>card('badge',Text(value));
 Widget accordion(Widget child)=>labels.identify('accordion','prime_button',ExpansionTile(title:Text(labels.text('accordion')),children:[child]));
 Widget menu(Map<String,String> options,ValueChanged<String> selected,{Set<String> disabled=const {}}){if(options.length>100)throw ArgumentError('Bounded menu required');final entries=options.entries.toList(growable:false);return labels.identify('menu','prime_button',PopupMenuButton<String>(tooltip:labels.text('menu'),onSelected:selected,itemBuilder:(context)=>[for(var i=0;i<entries.length;i++)PopupMenuItem(value:entries[i].key,enabled:!disabled.contains(entries[i].key),child:Semantics(identifier:labels.id('menuItem','prime_button',suffix:'-$i'),child:Text(entries[i].value)))],child:ConstrainedBox(constraints:const BoxConstraints(minHeight:kMinInteractiveDimension,minWidth:kMinInteractiveDimension),child:Center(child:Text(labels.text('menu'))))));}
 Widget tooltip(String message)=>PrimeCatalogueTooltip(key:ValueKey(scope),labels:labels,message:message);
 Widget tabs(List<String> keys,List<Widget> children,double height){if(keys.length!=children.length||keys.isEmpty||!height.isFinite||height<=0)throw ArgumentError('Bounded tabs required');return labels.identify('tabs','prime_card',DefaultTabController(length:keys.length,child:SizedBox(height:height,child:Column(children:[TabBar(tabs:[for(final key in keys)labels.identify(key,'prime_button',Tab(text:labels.text(key)))]),Expanded(child:TabBarView(children:children))]))));}
 Widget form(GlobalKey<FormState> key,List<Widget> fields,Future<void> Function() submit,{required double minColumnWidth,required double gap})=>labels.identify('form','prime_card',Form(key:key,child:PrimeResponsiveForm(minColumnWidth:minColumnWidth,gap:gap,children:[...fields,button('confirm',()async{if(key.currentState!.validate()){await submit();}else{throw StateError('invalid_form');}},suffix:'-form')])));
 Widget state(String key,{VoidCallback? retry})=>labels.identify(key,'prime_card',Semantics(liveRegion:key!='loading',child:Column(mainAxisSize:MainAxisSize.min,children:[Text(labels.text(key)),if(['loading','splash'].contains(key))CircularProgressIndicator(semanticsLabel:labels.text(key)),if(key=='error'&&retry!=null)button('retry',()async=>retry())])));
 Widget feedback(String message,VoidCallback dismiss,{bool error=false})=>labels.identify('toast','prime_card',Builder(builder:(context){final colors=Theme.of(context).colorScheme;return Semantics(liveRegion:true,label:labels.text(error?'error':'toast'),child:Card(color:error?colors.errorContainer:null,child:Column(mainAxisSize:MainAxisSize.min,children:[Text(message,style:error?TextStyle(color:colors.onErrorContainer):null),button('close',()async=>dismiss(),suffix:'-toast')]))); }));
 Widget preview(Widget child)=>card('preview',child);
}
class PrimeCatalogueRadio extends StatelessWidget {
 final CatalogueLabels labels;final Map<String,String> options;final String? value;final ValueChanged<String?> changed;final bool enabled;
 const PrimeCatalogueRadio({super.key,required this.labels,required this.options,required this.value,required this.changed,this.enabled=true});
 @override Widget build(BuildContext context){if(options.length>100)throw ArgumentError('Bounded options required');final entries=options.entries.toList(growable:false);return labels.identify('radio','prime_radio',Semantics(label:labels.text('radio'),container:true,child:RadioGroup<String>(groupValue:value,onChanged:changed,child:Column(children:[for(var i=0;i<entries.length;i++)Semantics(identifier:labels.id('radio','prime_radio',suffix:'-$i'),child:RadioListTile<String>(value:entries[i].key,enabled:enabled,title:Text(entries[i].value)))]))));}
}
