class _PrimeCatalogueTooltipState extends State<PrimeCatalogueTooltip>{bool visible=false,focused=false,hovered=false;void show(bool value){if(mounted)setState(()=>visible=value);}@override Widget build(BuildContext context)=>widget.labels.identify('tooltip','prime_card',MouseRegion(onEnter:(_){hovered=true;show(true);},onExit:(_){hovered=false;show(focused);},child:Focus(onFocusChange:(value){focused=value;show(value||hovered);},child:CallbackShortcuts(bindings:{const SingleActivator(LogicalKeyboardKey.escape):()=>show(false)},child:Column(mainAxisSize:MainAxisSize.min,children:[widget.labels.identify('tooltipTrigger','prime_button',TextButton(onPressed:()=>show(!visible),child:Text(widget.labels.text('tooltipTrigger')))),if(visible)Semantics(liveRegion:true,child:Text(widget.message))])))));}
class PrimeResponsiveForm extends StatelessWidget {
 final List<Widget> children;final double minColumnWidth,gap;
 const PrimeResponsiveForm({super.key,required this.children,required this.minColumnWidth,required this.gap});
 @override Widget build(BuildContext context)=>LayoutBuilder(builder:(context,c){final n=responsiveColumns(c.maxWidth,minColumnWidth,gap),width=((c.maxWidth-gap*(n-1))/n).clamp(0,double.infinity).toDouble();return Wrap(spacing:gap,runSpacing:gap,children:[for(final child in children)SizedBox(width:width,child:child)]);});
}
class PrimeAsyncBoundary<T> extends StatelessWidget {
 final String scope;final Future<T> future;final CatalogueLabels labels;final Widget Function(T) builder;
 const PrimeAsyncBoundary({super.key,required this.scope,required this.future,required this.labels,required this.builder});
 @override Widget build(BuildContext context)=>FutureBuilder<T>(key:ValueKey(scope),future:future,builder:(context,s){final kit=PrimeComponentKit(labels,scope);if(s.connectionState!=ConnectionState.done)return kit.state('loading');if(s.hasError)return kit.state('error');if(s.data==null)return kit.state('empty');return builder(s.data as T);});
}
