class _PrimeCountdownState extends State<PrimeCountdown> with WidgetsBindingObserver {Timer? timer;bool fired=false;int generation=0;int get value=>fired?0:remainingSeconds(widget.deadline,(widget.now??()=>DateTime.now().millisecondsSinceEpoch)());@override void initState(){super.initState();WidgetsBinding.instance.addObserver(this);_start();}void _start(){timer?.cancel();final g=++generation;fired=false;timer=Timer.periodic(const Duration(seconds:1),(_)=>_tick());WidgetsBinding.instance.addPostFrameCallback((_){if(mounted&&g==generation)_tick();});}void _tick(){if(!mounted)return;final zero=value==0;setState((){});if(zero&&!fired){fired=true;timer?.cancel();widget.onFinish?.call();}}@override void didUpdateWidget(covariant PrimeCountdown old){super.didUpdateWidget(old);if(old.scope!=widget.scope||old.deadline!=widget.deadline)_start();}@override void didChangeAppLifecycleState(AppLifecycleState state){if(state==AppLifecycleState.resumed)_tick();}@override void dispose(){generation++;timer?.cancel();WidgetsBinding.instance.removeObserver(this);super.dispose();}@override Widget build(BuildContext context)=>widget.labels.identify('countdown','prime_card',Semantics(liveRegion:fired,label:widget.labels.text('countdown'),child:Text(fired?widget.labels.text('finished'):value.toString())));}
