class _PrimeCatalogueModalState extends State<PrimeCatalogueModal>{final focus=FocusNode();DialogRoute<bool>? route;NavigatorState? nav;void _retire(){final r=route,n=nav;route=null;nav=null;if(r!=null&&n!=null)WidgetsBinding.instance.addPostFrameCallback((_){if(n.mounted&&r.isActive)n.removeRoute(r);});}@override void didUpdateWidget(covariant PrimeCatalogueModal old){super.didUpdateWidget(old);if(old.scope!=widget.scope)_retire();}@override void dispose(){_retire();focus.dispose();super.dispose();}Future<void> _open()async{if(route!=null)return;final l=widget.labels,scope=widget.scope,control=widget.control,child=widget.child,approve=widget.approve,n=Navigator.of(context);final r=DialogRoute<bool>(context:context,barrierLabel:l.text('close'),builder:(context){final kit=PrimeComponentKit(l,scope);return Dialog(alignment:control=='drawer'?AlignmentDirectional.centerEnd:null,child:l.identify(control,'prime_card',Column(mainAxisSize:MainAxisSize.min,children:[Flexible(child:SingleChildScrollView(child:child)),if(approve!=null)kit.button('confirm',()async{await approve();if(context.mounted&&mounted&&widget.scope==scope&&identical(ModalRoute.of(context),route)){final owned=route!;if(owned.isCurrent){Navigator.of(context).pop(true);}else{n.removeRoute(owned);}}},suffix:'-$control'),kit.button(approve==null?'close':'cancel',()async=>Navigator.of(context).pop(false),suffix:'-$control')])));});route=r;nav=n;await n.push(r);if(mounted&&route==r){route=null;nav=null;if(ModalRoute.of(context)?.isCurrent??false)focus.requestFocus();}}@override Widget build(BuildContext context)=>Semantics(identifier:widget.labels.id(widget.control=='drawer'?'menu':'button','prime_button',suffix:'-${widget.control}'),child:TextButton(focusNode:focus,onPressed:_open,child:Text(widget.labels.text(widget.control))));}
